#include <iostream>
#include <string>
class Sales_data {
public:
    Sales_data() = default;
    Sales_data(const std::string &s) : bookNo(s) {}
    Sales_data(const std::string &s, unsigned n, double p) : bookNo(s), units_sold(n), revenue(p) {}
    Sales_data(std::istream &is);
    void print() const { std::cout << bookNo << ' ' << units_sold << ' ' << revenue << std::endl; }
private:
    std::string bookNo;
    unsigned units_sold = 0;
    double revenue = 0.0;
};
Sales_data::Sales_data(std::istream &is) { is >> bookNo >> units_sold >> revenue; }
int main() {
    Sales_data book1;          book1.print();
    Sales_data book2("978-0596004673"); book2.print();
    Sales_data book3("978-0596004673", 5, 25.0); book3.print();
    std::istream &is = std::cin; 
    Sales_data book4(is); book4.print();
    return 0;
}
